import { type ProviderRegistryEntry } from "./types.js";

/**
 * Plain signs webhooks with a `Plain-Request-Signature` header carrying a bare hex-encoded
 * HMAC-SHA256 of the raw request body, keyed by the workspace's HMAC secret (generated by an admin in
 * Settings > Request signing, used as UTF-8). The signature covers no timestamp; Plain's SDK instead
 * rejects deliveries whose body `webhookMetadata.webhookDeliveryAttemptTimestamp` (ISO 8601) is more
 * than 300 seconds off. The event type rides the top-level `type` field (also `payload.eventType` and
 * the `Plain-Event-Type` header), and the top-level `id` is the event id, stable across retries.
 */
export const entry: ProviderRegistryEntry = {
  id: "plain",
  label: "Plain",
  category: "support",
  docsUrl: "https://www.plain.com/docs/api-reference/webhooks",
  secretProvisioning: "provider",
  eventTypeSource: { from: "body", path: "type" },
  sampleSource: "handauthored",
};
